<div class="loading" role="status"><span class="spinner" aria-hidden="true"></span><span>Loading Pipeline Definition…</span></div>
<style>.loading{display:flex;align-items:center;gap:.75rem;border:1px solid var(--color-border);border-radius:var(--radius-md);background:var(--color-surface);padding:var(--space-5);color:var(--color-text-muted)}.spinner{width:1.1rem;height:1.1rem;border:2px solid var(--color-border);border-top-color:var(--color-primary);border-radius:50%;animation:spin .7s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.spinner{animation:none}}</style>
